// History API returns the latest 100 calculations, newest first.
const clientId = $('Webhook').first().json.query.client_id || 'anonymous';
const { statusCode, body } = $input.first().json;
if (statusCode !== 200 || !Array.isArray(body)) {
  return [{ json: { status: 502, response: { error: 'calculator unavailable' } } }];
}

const FUNCTION_CALL = /\b(asin|acos|atan|sin|cos|tan|sqrt|log|ln|exp|abs|floor|ceil|degrees|radians|factorial)\s*\(/g;
const count = (counter, key) => { counter[key] = (counter[key] ?? 0) + 1; };
const byFrequency = (counter) => Object.fromEntries(Object.entries(counter).sort((a, b) => b[1] - a[1]));

const functions = {};
const operators = {};
const results = [];
for (const { expression, result } of body) {
  for (const [, name] of expression.matchAll(FUNCTION_CALL)) count(functions, name);
  for (const op of expression.match(/[+\-*/%^]/g) ?? []) count(operators, op);
  const value = Number(result);
  if (Number.isFinite(value)) results.push(value);
}

return [{ json: { status: 200, response: {
  client_id: clientId,
  calculations: body.length,
  first_at: body.at(-1)?.created_at ?? null,
  last_at: body[0]?.created_at ?? null,
  functions: byFrequency(functions),
  operators: byFrequency(operators),
  results: results.length
    ? { min: Math.min(...results), max: Math.max(...results), avg: results.reduce((a, b) => a + b, 0) / results.length }
    : null,
  note: 'based on the latest 100 calculations',
} } }];
